package edu.seu.vcampus.common.course;
import java.io.*; import java.util.*;
/** Creates an offering and its aggregate schedule rows. */
public record CreateOfferingCommand(String termId,String courseId,String teacherUserId,String className,int capacity,String offeringStatus,List<ScheduleInput> schedules) implements Serializable { @Serial private static final long serialVersionUID=1L; public CreateOfferingCommand{Objects.requireNonNull(termId);Objects.requireNonNull(courseId);Objects.requireNonNull(teacherUserId);Objects.requireNonNull(className);Objects.requireNonNull(offeringStatus);schedules=List.copyOf(schedules);if(termId.isBlank()||courseId.isBlank()||teacherUserId.isBlank()||className.isBlank()||capacity<1)throw new IllegalArgumentException("invalid offering");} public record ScheduleInput(String dayOfWeek,int startPeriod,int endPeriod,int startWeek,int endWeek,String classroom) implements Serializable{@Serial private static final long serialVersionUID=1L;} }
